41	// If offload is enabled, ensure that device DeviceID has been initialized.
42	//
43	// The return bool indicates if the offload is to the host device
44	// There are three possible results:
45	// - Return false if the target device is ready for offload
46	// - Return true without reporting a runtime error if offload is
47	//   disabled, perhaps because the initial device was specified.
48	// - Report a runtime error and return true.
49	//
50	// If DeviceID == OFFLOAD_DEVICE_DEFAULT, set DeviceID to the default device.
51	// This step might be skipped if offload is disabled.
52	bool checkDevice(int64_t &DeviceID, ident_t *Loc) {
53	  if (OffloadPolicy::get(*PM).Kind == OffloadPolicy::DISABLED) {
54	    ODBG(ODT_Device) << "Offload is disabled";
55	    return true;
56	  }
57	
58	  if (DeviceID == OFFLOAD_DEVICE_DEFAULT) {
59	    DeviceID = omp_get_default_device();
60	    ODBG(ODT_Device) << "Use default device id " << DeviceID;
61	  }
62	
63	  // Proposed behavior for OpenMP 5.2 in OpenMP spec github issue 2669.
64	  if (omp_get_num_devices() == 0) {
65	    ODBG(ODT_Device) << "omp_get_num_devices() == 0 but offload is manadatory";
66	    handleTargetOutcome(false, Loc);
67	    return true;
68	  }
69	
70	  if (isInitialDevice(static_cast<int>(DeviceID))) {
71	    ODBG(ODT_Device) << "Device is host (" << DeviceID
72	                     << "), returning as if offload is disabled";
73	    return true;
74	  }
75	  return false;
76	}
