113	
114	template <typename TargetAsyncInfoTy>
115	static inline void
116	targetData(ident_t *Loc, int64_t DeviceId, int32_t ArgNum, void **ArgsBase,
117	           void **Args, int64_t *ArgSizes, int64_t *ArgTypes,
118	           map_var_info_t *ArgNames, void **ArgMappers,
119	           TargetDataFuncPtrTy TargetDataFunction, const char *RegionTypeMsg,
120	           const char *RegionName) {
121	  assert(PM && "Runtime not initialized");
122	  static_assert(std::is_convertible_v<TargetAsyncInfoTy &, AsyncInfoTy &>,
123	                "TargetAsyncInfoTy must be convertible to AsyncInfoTy.");
124	
125	  TIMESCOPE_WITH_DETAILS_AND_IDENT("Runtime: Data Copy",
126	                                   "NumArgs=" + std::to_string(ArgNum), Loc);
127	
128	  ODBG(ODT_Interface) << "Entering data " << RegionName << " region for device "
129	                      << DeviceId << " with " << ArgNum << " mappings";
130	
131	  if (checkDevice(DeviceId, Loc)) {
132	    ODBG(ODT_Interface) << "Not offloading to device " << DeviceId;
133	    return;
134	  }
135	
136	  if (getInfoLevel() & OMP_INFOTYPE_KERNEL_ARGS)
137	    printKernelArguments(Loc, DeviceId, ArgNum, ArgSizes, ArgTypes, ArgNames,
138	                         RegionTypeMsg);
139	  ODBG_OS(ODT_Kernel, [&](llvm::raw_ostream &Os) {
140	    for (int I = 0; I < ArgNum; ++I) {
141	      Os << "Entry " << llvm::format("%2d", I) << ": Base=" << ArgsBase[I]
142	         << ", Begin=" << Args[I] << ", Size=" << ArgSizes[I]
143	         << ", Type=" << llvm::format("0x%" PRIx64, ArgTypes[I]) << ", Name="
144	         << ((ArgNames) ? getNameFromMapping(ArgNames[I]) : "unknown") << "\n";
145	    }
146	  });
147	
148	  auto DeviceOrErr = PM->getDevice(DeviceId);
149	  if (!DeviceOrErr)
150	    FATAL_MESSAGE(DeviceId, "%s", toString(DeviceOrErr.takeError()).c_str());
151	
152	  TargetAsyncInfoTy TargetAsyncInfo(*DeviceOrErr);
153	  AsyncInfoTy &AsyncInfo = TargetAsyncInfo;
154	
155	  /// RAII to establish tool anchors before and after data begin / end / update
156	  OMPT_IF_BUILT(assert((TargetDataFunction == targetDataBegin ||
157	                        TargetDataFunction == targetDataEnd ||
158	                        TargetDataFunction == targetDataUpdate) &&
159	                       "Encountered unexpected TargetDataFunction during "
160	                       "execution of targetData");
161	                auto CallbackFunctions =
162	                    (TargetDataFunction == targetDataBegin)
163	                        ? RegionInterface.getCallbacks<ompt_target_enter_data>()
164	                    : (TargetDataFunction == targetDataEnd)
165	                        ? RegionInterface.getCallbacks<ompt_target_exit_data>()
166	                        : RegionInterface.getCallbacks<ompt_target_update>();
167	                InterfaceRAII TargetDataRAII(CallbackFunctions, DeviceId,
168	                                             OMPT_GET_RETURN_ADDRESS);)
169	
170	  int Rc = OFFLOAD_SUCCESS;
171	
172	  // Allocate StateInfo for targetDataBegin and targetDataEnd to track
173	  // allocations, pointer attachments and deferred transfers.
174	  // This is not needed for targetDataUpdate.
175	  std::unique_ptr<StateInfoTy> StateInfo;
176	  if (TargetDataFunction == targetDataBegin ||
177	      TargetDataFunction == targetDataEnd)
178	    StateInfo = std::make_unique<StateInfoTy>();
179	
180	  Rc = TargetDataFunction(Loc, *DeviceOrErr, ArgNum, ArgsBase, Args, ArgSizes,
181	                          ArgTypes, ArgNames, ArgMappers, AsyncInfo,
182	                          StateInfo.get(), /*FromMapper=*/false);
183	
184	  if (Rc == OFFLOAD_SUCCESS) {
185	    // Process deferred ATTACH entries BEFORE synchronization
186	    if (StateInfo && !StateInfo->AttachEntries.empty())
187	      Rc = processAttachEntries(*DeviceOrErr, *StateInfo, AsyncInfo);
188	
189	    if (Rc == OFFLOAD_SUCCESS)
190	      Rc = AsyncInfo.synchronize();
191	  }
192	
193	  handleTargetOutcome(Rc == OFFLOAD_SUCCESS, Loc);
194	}
