278	/// Holds dynamically allocated argument arrays when upgrading old-format
279	/// kernel arguments to include the dyn_ptr slot.
280	struct UpgradedArgBuffersTy {
281	  llvm::SmallVector<void *, 0> BasePtrs;
282	  llvm::SmallVector<void *, 0> Ptrs;
283	  llvm::SmallVector<int64_t, 0> Sizes;
284	  llvm::SmallVector<int64_t, 0> Types;
285	  llvm::SmallVector<map_var_info_t, 0> Names;
286	  llvm::SmallVector<void *, 0> Mappers;
287	};
288	
289	static KernelArgsTy *upgradeKernelArgs(KernelArgsTy *KernelArgs,
290	                                       KernelArgsTy &LocalKernelArgs,
291	                                       UpgradedArgBuffersTy &Bufs,
292	                                       int32_t NumTeams, int32_t ThreadLimit) {
293	  if (KernelArgs->Version > OMP_KERNEL_ARG_VERSION)
294	    ODBG(ODT_Interface) << "Unexpected ABI version: " << KernelArgs->Version;
295	
296	  // Versions before OMP_KERNEL_ARG_MIN_VERSION_WITH_DYN_PTR used an older
297	  // struct layout missing several fields. Reconstruct a complete struct.
298	  if (KernelArgs->Version < OMP_KERNEL_ARG_MIN_VERSION_WITH_DYN_PTR) {
299	    // Maintain the version so the runtime can match the device ABI.
300	    LocalKernelArgs.Version = KernelArgs->Version;
301	    LocalKernelArgs.NumArgs = KernelArgs->NumArgs;
302	    LocalKernelArgs.ArgBasePtrs = KernelArgs->ArgBasePtrs;
303	    LocalKernelArgs.ArgPtrs = KernelArgs->ArgPtrs;
304	    LocalKernelArgs.ArgSizes = KernelArgs->ArgSizes;
305	    LocalKernelArgs.ArgTypes = KernelArgs->ArgTypes;
306	    LocalKernelArgs.ArgNames = KernelArgs->ArgNames;
307	    LocalKernelArgs.ArgMappers = KernelArgs->ArgMappers;
308	    LocalKernelArgs.Tripcount = KernelArgs->Tripcount;
309	    LocalKernelArgs.Flags = KernelArgs->Flags;
310	    LocalKernelArgs.DynCGroupMem = 0;
311	    LocalKernelArgs.UserNumBlocks[0] = NumTeams;
312	    LocalKernelArgs.UserNumBlocks[1] = 1;
313	    LocalKernelArgs.UserNumBlocks[2] = 1;
314	    LocalKernelArgs.UserThreadLimit[0] = ThreadLimit;
315	    LocalKernelArgs.UserThreadLimit[1] = 1;
316	    LocalKernelArgs.UserThreadLimit[2] = 1;
317	    return &LocalKernelArgs;
318	  }
319	
320	  // FIXME: This is a WA to "calibrate" the bad work done in the front end.
321	  // Delete this ugly code after the front end emits proper values.
322	  auto CorrectMultiDim = [](uint32_t (&Val)[3]) {
323	    if (Val[1] == 0)
324	      Val[1] = 1;
325	    if (Val[2] == 0)
326	      Val[2] = 1;
327	  };
328	  CorrectMultiDim(KernelArgs->UserThreadLimit);
329	  CorrectMultiDim(KernelArgs->UserNumBlocks);
330	
331	  // Version 3 put the implicit argument at the front with no storage.
332	  if (KernelArgs->Version == OMP_KERNEL_ARG_MIN_VERSION_WITH_DYN_PTR) {
333	    uint32_t NewSize = KernelArgs->NumArgs + 1;
334	
335	    Bufs.BasePtrs.resize(NewSize, nullptr);
336	    Bufs.Ptrs.resize(NewSize, nullptr);
337	    Bufs.Sizes.resize(NewSize, 0);
338	    Bufs.Types.resize(NewSize, 0);
339	    Bufs.Names.resize(NewSize, nullptr);
340	    Bufs.Mappers.resize(NewSize, nullptr);
341	
342	    for (uint32_t I = 0; I < KernelArgs->NumArgs; ++I) {
343	      Bufs.BasePtrs[I] = KernelArgs->ArgBasePtrs[I];
344	      Bufs.Ptrs[I] = KernelArgs->ArgPtrs[I];
345	      Bufs.Sizes[I] = KernelArgs->ArgSizes[I];
346	      Bufs.Types[I] = KernelArgs->ArgTypes[I];
347	      if (KernelArgs->ArgNames)
348	        Bufs.Names[I] = KernelArgs->ArgNames[I];
349	      if (KernelArgs->ArgMappers)
350	        Bufs.Mappers[I] = KernelArgs->ArgMappers[I];
351	    }
352	
353	    Bufs.Types[KernelArgs->NumArgs] =
354	        OMP_TGT_MAPTYPE_TARGET_PARAM | OMP_TGT_MAPTYPE_LITERAL;
355	
356	    LocalKernelArgs = *KernelArgs;
357	    LocalKernelArgs.NumArgs = NewSize;
358	    LocalKernelArgs.ArgBasePtrs = Bufs.BasePtrs.data();
359	    LocalKernelArgs.ArgPtrs = Bufs.Ptrs.data();
360	    LocalKernelArgs.ArgSizes = Bufs.Sizes.data();
361	    LocalKernelArgs.ArgTypes = Bufs.Types.data();
362	    LocalKernelArgs.ArgNames = Bufs.Names.data();
363	    LocalKernelArgs.ArgMappers = Bufs.Mappers.data();
364	    return &LocalKernelArgs;
365	  }
366	
367	  return KernelArgs;
368	}
